#!/usr/bin/env python3
# Generated by morzsa via A2A Mesh delegation
"""
Golden-file oracle for A2A Mesh message types.

Idea: minden üzenettípushoz referencia-payload tesztlaborban,
CI diff-fel — regresszió (mint az @-csonkolódás) azonnal kiderül.

Usage:
    python golden_oracle.py generate   # (re)generate golden files from definitions
    python golden_oracle.py validate    # validate all golden files against definitions
    python golden_oracle.py diff <file>  # diff a payload file against its golden counterpart
    python golden_oracle.py check <msg_type> <payload_json>  # check a single payload
    python golden_oracle.py list         # list all known message types
"""

from __future__ import annotations

import json
