from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------

REPO_ROOT = Path(__file__).resolve().parent
GOLDEN_DIR = REPO_ROOT / "tests" / "golden"
GOLDEN_DIR.mkdir(parents=True, exist_ok=True)

# ---------------------------------------------------------------------------
# Message type definitions — the "contract" for each A2A Mesh message
# ---------------------------------------------------------------------------

@dataclass
class FieldSpec:
    name: str
    type_name: str          # e.g. "str", "int", "list", "dict"
    required: bool = True
    min_len: Optional[int] = None
    max_len: Optional[int] = None
    pattern: Optional[str] = None   # substring that MUST appear (e.g. "@" for handles)
    description: str = ""

@dataclass
class MessageType:
    msg_type: str
    description: str
    fields: List[FieldSpec] = field(default_factory=list)
    reference_payload: Dict[str, Any] = field(default_factory=dict)

# ---------------------------------------------------------------------------
# Registry of known message types with reference payloads
# ---------------------------------------------------------------------------

MESSAGE_TYPES: Dict[str, MessageType] = {}

def register(mt: MessageType) -> MessageType:
    MESSAGE_TYPES[mt.msg_type] = mt
    return mt

