# ---------------------------------------------------------------------------
# Validation logic
# ---------------------------------------------------------------------------

class ValidationError(Exception):
    pass

def _check_type(value: Any, type_name: str) -> bool:
    mapping = {
        "str": str,
        "int": int,
        "float": (int, float),
        "bool": bool,
        "list": list,
        "dict": dict,
    }
    expected = mapping.get(type_name)
    if expected is None:
        return True
    if type_name == "bool":
        return isinstance(value, bool)
    if type_name == "int":
        return isinstance(value, int) and not isinstance(value, bool)
    return isinstance(value, expected)

def validate_payload(msg_type: str, payload: Dict[str, Any]) -> List[str]:
    """
    Validate a payload against the message type spec.
    Returns a list of error strings (empty if valid).
    """
    errors: List[str] = []
    mt = MESSAGE_TYPES.get(msg_type)
    if mt is None:
        return [f"Unknown message type: {msg_type!r}"]

    for spec in mt.fields:
        if spec.name not in payload:
            if spec.required:
                errors.append(f"Missing required field: {spec.name}")
            continue
        value = payload[spec.name]

        if not _check_type(value, spec.type_name):
            errors.append(
                f"Field {spec.name!r}: expected {spec.type_name}, got {type(value).__name__}"
            )
            continue

        if spec.type_name == "str":
            sval = value
            if spec.min_len is not None and len(sval) < spec.min_len:
                errors.append(
                    f"Field {spec.name!r}: length {len(sval)} < min {spec.min_len}"
                )
            if spec.max_len is not None and len(sval) > spec.max_len:
                errors.append(
                    f"Field {spec.name!r}: length {len(sval)} > max {spec.max_len}"
                )
            if spec.pattern is not None and spec.pattern not in sval:
                errors.append(
                    f"Field {spec.name!r}: required pattern {spec.pattern!r} not found "
                    f"(possible truncation)"
                )
        elif spec.type_name == "list":
            if spec.min_len is not None and len(value) < spec.min_len:
                errors.append(
                    f"Field {spec.name!r}: list length {len(value)} < min {spec.min_len}"
                )

    # Check for leftover template placeholders — the original bug that motivated this idea
    for key, val in payload.items():
        if isinstance(val, str) and ("{" in val and "}" in val):
            # Heuristic: detect unreplaced placeholders like {agent}
            import re
            if re.search(r"\{[a-zA-Z_][a-zA-Z0-9_]*\}", val):
                errors.append(
                    f"Field {key!r}: unreplaced template placeholder detected in value: {val!r}"
                )

    return errors

# ---------------------------------------------------------------------------
# Golden file management
# ---------------------------------------------------------------------------

def golden_file_path(msg_type: str) -> Path:
    safe = msg_type.replace("/", "_")
    return GOLDEN_DIR / f"{safe}.golden.json"

def generate_golden_files() -> List[str]:
    """Write reference payloads to disk as golden files."""
    written: List[str] = []
    for msg_type, mt in MESSAGE_TYPES.items():
        path = golden_file_path(msg_type)
        # Validate our own reference payload first
        errs = validate_payload(msg_type, mt.reference_payload)
        if errs:
            print(f"WARNING: reference payload for {msg_type} has errors:", file=sys.stderr)
            for e in errs:
                print(f"  - {e}", file=sys.stderr)
        canonical = json.dumps(mt.reference_payload, sort_keys=True, indent=2, ensure_ascii=False)
        path.write_text(canonical + "\n", encoding="utf-8")
        written.append(str(path.relative_to(REPO_ROOT)))
    return written

def validate_golden_files() -> Tuple[int, int]:
    """Validate all golden files on disk. Returns (passed, failed)."""
    passed = 0
    failed = 0
    for msg_type, mt in MESSAGE_TYPES.items():
        path = golden_file_path(msg_type)
        if not path.exists():
            print(f"FAIL  {msg_type}: golden file missing at {path}")
            failed += 1
            continue
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except json.JSONDecodeError as exc:
            print(f"FAIL  {msg_type}: invalid JSON: {exc}")
            failed += 1
            continue

        errs = validate_payload(msg_type, data)
        if errs:
            print(f"FAIL  {msg_type}:")
            for e in errs:
                print(f"  - {e}")
            failed += 1
        else:
            print(f"PASS  {msg_type}")
            passed += 1
    return passed, failed

def diff_against_golden(payload_file: str) -> int:
    """Diff a payload file against its golden counterpart (by msg_type field)."""
    p = Path(payload_file)
    if not p.exists():
        print(f"Error: file not found: {payload_file}", file=sys.stderr)
        return 2
    try:
        data = json.loads(p.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        print(f"Error: invalid JSON in {payload_file}: {exc}", file=sys.stderr)
        return 2

    msg_type = data.get("msg_type") or data.get("type")
    if not msg_type:
        print("Error: payload has no 'msg_type' or 'type' field", file=sys.stderr)
        return 2

    golden_path = golden_file_path(msg_type)
    if not golden_path.exists():
        print(f"Error: no golden file for message type {msg_type!r}", file=sys.stderr)
        return 2

    golden = json.loads(golden_path.read_text(encoding="utf-8"))

    # Structural validation
    errs = validate_payload(msg_type, data)
    if errs:
        print(f"VALIDATION ERRORS for {msg_type}:")
        for e in errs:
            print(f"  - {e}")

    # Field-by-field diff
    all_keys = sorted(set(list(golden.keys()) + list(data.keys())))
    has_diff = False
    for key in all_keys:
        gval = golden.get(key, "<MISSING>")
        dval = data.get(key, "<MISSING>")
        if gval != dval:
            has_diff = True
            print(f"  {key}:")
            print(f"    golden : {gval!r}")
            print(f"    actual : {dval!r}")

    if not has_diff and not errs:
        print(f"OK: {payload_file} matches golden file for {msg_type!r}")
        return 0
    return 1

def check_single(msg_type: str, payload_json: str) -> int:
    """Validate a single payload given as JSON string."""
    try:
        data = json.loads(payload_json)
    except json.JSONDecodeError as exc:
        print(f"Error: invalid JSON: {exc}", file=sys.stderr)
        return 2
    errs = validate_payload(msg_type, data)
    if errs:
        print(f"FAIL  {msg_type}:")
        for e in errs:
            print(f"  - {e}")
        return 1
    print(f"PASS  {msg_type}")
    return 0

def list_types() -> None:
    for msg_type, mt in MESSAGE_TYPES.items():
        print(f"  {msg_type:20s}  {mt.description}")

# ---------------------------------------------------------------------------
# CI-friendly summary
# ---------------------------------------------------------------------------

def ci_summary() -> int:
    """Run full validation and print a CI-friendly summary. Exit code 0/1."""
    print("=" * 60)
    print("Golden-file oracle — CI validation")
    print("=" * 60)
    passed, failed = validate_golden_files()
    print("-" * 60)
    print(f"Total: {passed + failed}  Passed: {passed}  Failed: {failed}")
    print("=" * 60)
    return 0 if failed == 0 else 1

# ---------------------------------------------------------------------------
# Main CLI
# ---------------------------------------------------------------------------

USAGE = textwrap.dedent("""\
    Usage:
      golden_oracle.py generate              Generate/refresh golden files
      golden_oracle.py validate              Validate all golden files
      golden_oracle.py diff <file>           Diff a payload file against golden
      golden_oracle.py check <type> <json>   Validate a single payload
      golden_oracle.py list                  List known message types
      golden_oracle.py ci                    CI summary (exit 0/1)
""")

def main(argv: List[str]) -> int:
    if not argv:
        print(USAGE)
        return 0

    cmd = argv[0]
    rest = argv[1:]

    if cmd == "generate":
        written = generate_golden_files()
        print(f"Generated {len(written)} golden files:")
        for w in written:
            print(f"  {w}")
        return 0

    if cmd == "validate":
        passed, failed = validate_golden_files()
        print(f"\nPassed: {passed}  Failed: {failed}")
        return 0 if failed == 0 else 1

    if cmd == "diff":
        if not rest:
            print("Error: diff requires a file argument", file=sys.stderr)
            return 2
        return diff_against_golden(rest[0])

    if cmd == "check":
        if len(rest) < 2:
            print("Error: check requires <msg_type> <payload_json>", file=sys.stderr)
            return 2
        return check_single(rest[0], rest[1])

    if cmd == "list":
        list_types()
        return 0

    if cmd == "ci":
        return ci_summary()

    print(f"Unknown command: {cmd}", file=sys.stderr)
    print(USAGE, file=sys.stderr)
    return 2

if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))